function settingsLoader(){
    // Llamamos al root para modificar el estilo de el sistema operativo :O
    var r = document.querySelector(':root');

    let background = localStorage.getItem('settings_background') ?? false;
    let selection = localStorage.getItem('settings_selection') ?? false;
    let body = localStorage.getItem('settings_body') ?? false;
    // leemos y traspasamos los datos a el sistema

    //BACKGROUND
    if(background){
        //displaybackgroundchange(background);
    }else{
        localStorage.setItem('settings_background', '#008080');
    }

    //SELECTION
    if(selection){
        //displayselectionchange(selection);
    }else{
        localStorage.setItem('settings_selection', '#000080');
    }

    //BODY
    if(body){
        //displaybodychange(body);
    }else{
        localStorage.setItem('settings_body', '#c3c3c3');
    }
}

